    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private LinearLayout card(LinearLayout parent){LinearLayout value=new LinearLayout(this);value.setOrientation(LinearLayout.VERTICAL);value.setPadding(dp(16),dp(12),dp(16),dp(12));GradientDrawable background=new GradientDrawable();background.setColor(CARD);background.setCornerRadius(dp(16));value.setBackground(background);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.topMargin=dp(16);parent.addView(value,params);return value;}
    private TextView text(LinearLayout parent,String value,int size){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(TEXT);view.setPadding(0,dp(5),0,dp(5));parent.addView(view,new LinearLayout.LayoutParams(-1,-2));return view;}
    private Button button(LinearLayout parent,String label,boolean primary){Button value=new Button(this);value.setText(label);value.setAllCaps(false);value.setTextSize(16);value.setTextColor(new android.content.res.ColorStateList(new int[][]{{-android.R.attr.state_enabled},{}},new int[]{0xff6b503b,primary?0xffffffff:TEXT}));value.setMinHeight(dp(52));value.setMinimumHeight(dp(52));value.setPadding(dp(12),dp(10),dp(12),dp(10));android.graphics.drawable.StateListDrawable background=new android.graphics.drawable.StateListDrawable();background.addState(new int[]{-android.R.attr.state_enabled},buttonBackground(false,false,false));background.addState(new int[]{android.R.attr.state_pressed},buttonBackground(primary,false,true));background.addState(new int[]{android.R.attr.state_focused},buttonBackground(primary,true,false));background.addState(new int[]{},buttonBackground(primary,false,false));value.setStateListAnimator(null);value.setElevation(0);value.setBackgroundTintList(null);value.setBackground(background);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.topMargin=dp(8);parent.addView(value,params);return value;}
    private GradientDrawable buttonBackground(boolean primary,boolean focused,boolean pressed){GradientDrawable background=new GradientDrawable();background.setColor(primary?(pressed?0xff6b3717:PRIMARY):BG);background.setCornerRadius(dp(12));background.setStroke(dp(focused?3:1),focused?(primary?0xffffffff:TEXT):primary?PRIMARY:BORDER);return background;}
    private EditText field(LinearLayout parent,String label,String hint,boolean secret){TextView name=text(parent,label,16);EditText value=new EditText(this);value.setId(View.generateViewId());value.setTextSize(16);value.setTextColor(TEXT);value.setHint(hint);value.setMinHeight(dp(56));value.setMaxLines(secret?3:4);value.setSaveEnabled(false);value.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS|(secret?android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD:0));if(secret)value.setTransformationMethod(PasswordTransformationMethod.getInstance());value.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);value.setContentDescription(label);name.setLabelFor(value.getId());parent.addView(value,new LinearLayout.LayoutParams(-1,-2));return value;}
    private CheckBox check(LinearLayout parent,String label){CheckBox value=new CheckBox(this);value.setText(label);value.setTextColor(TEXT);value.setTextSize(16);value.setMinHeight(dp(52));value.setPadding(0,dp(8),0,dp(8));value.setButtonTintList(new android.content.res.ColorStateList(new int[][]{{android.R.attr.state_checked},{}},new int[]{PRIMARY,BORDER}));parent.addView(value,new LinearLayout.LayoutParams(-1,-2));return value;}
    private void run(Task task){if(busy)return;busy=true;setActionsEnabled(false);overall.setText("Vorgang läuft. Ein geprüfter Abschluss ist noch nicht bestätigt.");currentTask=WORK.submit(()->{try{task.run();}catch(Exception failure){ui(()->showError(safeCode(failure)));}finally{ui(()->{busy=false;setActionsEnabled(true);});}});}
    private void ui(Runnable runnable){runOnUiThread(()->{if(!isDestroyed())runnable.run();});}
    private void setActionsEnabled(boolean enabled){for(Button button:new Button[]{saveSetup,requestBackup,confirmRecovery,exportUsb,previewRestore,activateRestore,newGeneration,cancelRestore,repairKey,previewPrevious})if(button!=null)button.setEnabled(enabled);for(View field:new View[]{account,folder,automatic,unmetered,confirmation,restoreCode,repairCode,repairConfirmation,codeSeparate,legacyMediaCoverage})if(field!=null)field.setEnabled(enabled);}
    private static String safeCode(Exception failure){String value=failure.getMessage();return value!=null&&value.matches("(?:BACKUP|RESTORE|RECOVERY|DEVICE|DOCUMENT|ACCOUNT|AUTH|PERMISSION|PORTABLE)_[A-Z0-9_]{1,90}")?value:failure instanceof SecurityException?"PERMISSION_REQUIRED":"BACKUP_OPERATION_FAILED";}
    private void showError(String code){String message;
        switch(code){case "RECOVERY_CODE_INVALID":case "RECOVERY_CONFIRMATION_MISMATCH":message="Der Code stimmt nicht mit dem separat gespeicherten Code überein. Eingabe prüfen; die übrigen Daten bleiben erhalten.";if(secretErrorField!=null)secretErrorField.setError(message);break;
            case "RECOVERY_NOT_CONFIGURED":message="Zuerst den Wiederherstellungscode separat speichern und zurückbestätigen.";break;
            case "RECOVERY_KEYSTORE_UNAVAILABLE_USE_RECOVERY_CODE":case "RECOVERY_STORAGE_INVALID":message="Der lokale Schlüsselschutz kann nicht geöffnet werden. Er wird nicht ersetzt. Für eine Wiederherstellung den separat aufbewahrten Code und eine geprüfte Sicherung verwenden.";break;
            case "RECOVERY_REPAIR_NOT_REQUIRED":message="Der vorhandene Schlüsselschutz lässt sich öffnen und wird nicht ersetzt. Den bestehenden Code weiter getrennt aufbewahren.";break;
            case "DEVICE_LOCK_REQUIRED_FOR_RECOVERY_EXPORT":message="Für den erneuten Export des bestehenden Codes zuerst eine Android-Gerätesperre einrichten. Der geschützte Schlüssel und vorhandene Sicherungen bleiben erhalten.";break;
            case "BACKUP_SETTINGS_WRITE_CONFLICT":message="Die Einrichtung wurde inzwischen geändert. Eingaben bleiben erhalten; aktuellen Stand vergleichen und anschließend erneut speichern.";retrySetup.setVisibility(View.VISIBLE);break;
            case "BACKUP_BROWSER_STATE_TOO_LARGE":message="Die Browserentwürfe sind zu umfangreich für den zusätzlichen Entwurfscheckpoint. Offene Vorgänge in der App speichern und die Sicherung erneut anfordern.";break;
            case "BACKUP_BROWSER_EDITOR_STATE_MISMATCH":message="Die Entwurfsaufnahme wurde inzwischen geändert. Zur App zurückkehren und die Vollsicherung erneut öffnen. Die vorhandenen Entwürfe, Geschäftsdaten und letzte geprüfte Sicherung bleiben erhalten.";break;
            case "BACKUP_BROWSER_STATE_REQUIRED_OPEN_APP":case "BACKUP_BROWSER_CAPTURE_REQUIRED":case "BACKUP_BROWSER_WRITE_CONFLICT":message="Aktuelle Formularwerte sind noch nicht für die Vollsicherung erfasst. Zur App zurückkehren und die Vollsicherung erneut öffnen. Eingaben bleiben erhalten.";break;
            case "BACKUP_STORAGE_RESERVE_REQUIRED":case "RESTORE_SPACE_REQUIRED":message="Es fehlt freier Speicher für den geprüften Vorgang und die Reserve für lokale Arbeit. Speicher freigeben und ausdrücklich erneut versuchen. Vorhandene Sicherungen bleiben erhalten.";break;
            case "BACKUP_DRIVE_DESTINATION_REQUIRED":message="Bestehendes Google-Konto und Sicherungsordner ausdrücklich auswählen und lokal speichern.";break;
            case "PORTABLE_LOCAL_DESTINATION_REQUIRED":message="Für den unverschlüsselten Export einen Ordner auf dem Gerät oder USB wählen. Für Cloud-Ziele die verschlüsselte Vollsicherung verwenden.";break;
            case "DOCUMENT_READ_PERMISSION_REQUIRED":message="Die Dateiauswahl hat keinen Lesezugriff freigegeben. Sicherungsdatei erneut auswählen; der aktive Bestand bleibt unverändert.";break;
            case "DOCUMENT_READ_WRITE_PERMISSION_REQUIRED":message="Für dieses Sicherungsziel werden Lese- und Schreibzugriff benötigt. Ziel erneut bewusst auswählen; vorhandene Sicherungen bleiben erhalten.";break;
            case "PERMISSION_REQUIRED":case "AUTH_REQUIRED":message="Die Kontofreigabe oder der Dateizugriff fehlt. Zugriff am Gerät ausdrücklich prüfen; lokale Arbeit bleibt erhalten.";break;
            default:message="Vorgang nicht abgeschlossen ("+code+"). Eingaben bleiben erhalten. Status prüfen und nach Behebung erneut versuchen.";
        }overall.setText(message);overall.setTextColor(ERROR);overall.announceForAccessibility(message);}
    private void refresh(boolean initial){
        long serial=refreshSerial.incrementAndGet();String usbRequest=exportRequest,plainRequest=portableRequest;WORK.execute(()->{try(PixelLocalStore store=new PixelLocalStore(getApplicationContext())){
            JSONObject value=new FullBackupController(this,store).status(new JSONObject().put("offset",0).put("limit",30)),config=new BackupSettingsRepository(this,store).read(),pending=BackupRestoreService.pendingStatus(this),previous=new BackupRestoreService(this).previousPreservation();
            JSONObject usb=null,plain=null;if(!usbRequest.isEmpty())try{usb=new BackupSafService(this,store).status(usbRequest);}catch(Exception unknown){}if(!plainRequest.isEmpty())try{plain=new BackupPortableExport(this,store).status(plainRequest);}catch(Exception unknown){}final JSONObject usbState=usb,plainState=plain;
            ui(()->{if(serial!=refreshSerial.get())return;status=value;if(!setupLoaded){loading=true;if(restored!=null&&restored.getBoolean("setup_dirty",false)){account.setText(restored.getString("account",""));folder.setText(restored.getString("folder",""));automatic.setChecked(restored.getBoolean("automatic",false)&&config.optBoolean("contextMatches"));unmetered.setChecked(restored.getBoolean("unmetered",true));settingsRevision=restored.getString("settings_revision","");dirty=true;setup.setVisibility(View.VISIBLE);}else{String chosen=config.optString("account");if(chosen.isEmpty())chosen=getSharedPreferences("haus_garten",0).getString("drive_account","");account.setText(chosen);folder.setText(config.optString("folderId"));automatic.setChecked(config.optBoolean("enabled")&&config.optBoolean("contextMatches"));unmetered.setChecked(config.optBoolean("unmeteredOnly",true));settingsRevision=config.optString("revision");dirty=false;if(config.optString("folderId").isEmpty())setup.setVisibility(View.VISIBLE);}loading=false;setupLoaded=true;}renderStatus(value,config);renderPendingRestore(pending);renderPrevious(previous);if(usbState!=null)renderProviderStatus(jobStatus,usbState,false);if(plainState!=null)renderProviderStatus(portableStatus,plainState,true);});
        }catch(Exception failure){ui(()->showError(safeCode(failure)));}});
    }
    private static String time(String value){try{return DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm",Locale.GERMAN).withZone(ZoneId.of("Europe/Vienna")).format(Instant.parse(value));}catch(Exception missing){return "noch nicht bestätigt";}}
    private void renderStatus(JSONObject value,JSONObject config){
        overall.setTextColor(TEXT);String captured=value.optString("last_external_captured_at"),checked=value.optString("last_external_verified_at");
        String scope=value.optString("confirmation_scope"),destination=scope.equals("direct_drive_complete_hash_readback")?"Drive":scope.equals("removable_storage_complete_readback")?"angeschlossenem USB-Speicher":"externem Sicherungsziel";overall.setText(checked.isEmpty()?"Noch keine extern vollständig zurückgelesene und geprüfte Vollsicherung bestätigt. Lokales Speichern bleibt unabhängig davon möglich.":"Extern geprüfte Vollsicherung auf "+destination+": "+time(checked)+"\nEnthaltener Datenstand: "+time(captured)+"\nEin späterer Prüftermin macht ältere Daten nicht aktueller.");
        if(!value.optBoolean("media_checkpoint_ready"))overall.append("\nFotoentwürfe sind noch nicht vollständig in den geprüften lokalen Medienspeicher übernommen. Die Vollsicherung bleibt bis zur bestätigten Übernahme gesperrt; vorhandene Arbeit bleibt erhalten.");
        if(value.optBoolean("clock_review_required")){overall.append("\nGerätezeit und Sicherungszeiten prüfen. Ein Zeitstempel in der Zukunft bestätigt keinen aktuellen Datenstand.");overall.setTextColor(ERROR);}
        if(value.optBoolean("browser_capture_pending"))overall.append("\nAktuelle Formularwerte werden noch für die Vollsicherung erfasst. Status prüfen; noch keine neue Sicherung bestätigt.");else if(!value.optString("browser_checkpoint_error").isEmpty())showError(value.optString("browser_checkpoint_error"));
        setupSummary.setText(config.optString("folderId").isEmpty()?"Drive-Sicherungsziel noch nicht eingerichtet.":"Konto: "+config.optString("account")+"\nSicherungsordner: "+config.optString("folderId")+"\nAutomatisch täglich: "+(config.optBoolean("enabled")&&config.optBoolean("contextMatches")?"eingeschaltet":"ausgeschaltet")+(config.optBoolean("contextMatches")?"":"\nNach Wiederherstellung ist eine erneute ausdrückliche Einrichtung nötig."));
        boolean key=config.optBoolean("keyConfigured");recoveryStatus.setText(key?"Der bestätigte Code ist auf diesem Gerät im Keystore geschützt. Auf dem Ersatzgerät reicht der separat aufbewahrte Code. Eine vorhandene Schutzkapsel wird bei Fehlern nicht still ersetzt.":"Noch kein bestätigter Wiederherstellungscode. Code separat aufbewahren und zurückbestätigen. Verlust von Gerät und Code bedeutet nicht wiederherstellbare Sicherungen.");
        confirmation.setVisibility(key?View.GONE:View.VISIBLE);codeSeparate.setVisibility(key?View.GONE:View.VISIBLE);confirmRecovery.setVisibility(key?View.GONE:View.VISIBLE);
        jobs.removeAllViews();activeBackupId="";shownJobs.clear();jobOffset=0;JSONArray list=value.optJSONArray("jobs");jobsTotal=value.optInt("total",list==null?0:list.length());if(list==null||list.length()==0)text(jobs,"Noch keine Vollsicherungsgeneration vorhanden. Einrichtung abschließen und eine Sicherung anfordern.",16);renderJobs(list);
    }
    private void renderJobs(JSONArray list){if(list!=null)for(int i=0;i<list.length();i++){
            JSONObject job=list.optJSONObject(i);if(job==null)continue;String id=job.optString("backup_id"),phase=job.optString("phase");if(!shownJobs.add(id))continue;LinearLayout item=card(jobs);text(item,phaseLabel(phase),18);text(item,"Datenstand: "+time(job.optString("captured_at"))+"\nLokal geprüft: "+time(job.optString("local_verified_at"))+"\nDirekt auf Drive geprüft: "+time(job.optString("remote_verified_at"))+"\nDateianbieter zurückgelesen: "+time(job.optString("provider_verified_at")),16);
            if(job.optString("media_coverage").equals("LEGACY_NOT_PROVEN"))text(item,"Bei dieser älteren Generation ist die vollständige Abdeckung früherer Fotoentwürfe nicht belegt.",16);
            if(activeBackupId.isEmpty()&&job.optBoolean("context_matches")&&job.optBoolean("target_matches")&&!Arrays.asList("REMOTE_VERIFIED","PROVIDER_VERIFIED","CANCELLED").contains(phase))activeBackupId=id;
            if(!job.optString("last_error_code").isEmpty())text(item,"Hinweis: "+job.optString("last_error_code")+" · Versuche: "+job.optInt("attempts"),16);
            if(!job.optString("local_verified_at").isEmpty())button(item,"Diese Sicherung für Schlüsselschutz-Reparatur wählen",false).setOnClickListener(v->{if(busy)return;if(!repairBackupId.equals(id)){repairRequest=UUID.randomUUID().toString();repairCode.setText("");repairConfirmation.setText("");}repairBackupId=id;repairFields.setVisibility(View.VISIBLE);repairStatus.setText("Gewählte lokale Sicherung: "+id+"\nDatenstand: "+time(job.optString("captured_at"))+"\nDen separat aufbewahrten Code zweimal eingeben. Erst vollständige Archiv- und Bestandsprüfung erlaubt die Reparatur einer unlesbaren Kapsel.");repairStatus.requestFocus();});
            if(Arrays.asList("NEEDS_USER_ACTION","FAILED","RETRY_PENDING").contains(phase)&&job.optBoolean("context_matches",true)){Button retry=button(item,"Diese Sicherung erneut versuchen",false);final String[] action={""};retry.setOnClickListener(v->{if(action[0].isEmpty())action[0]=UUID.randomUUID().toString();run(()->{try(PixelLocalStore store=new PixelLocalStore(this)){new FullBackupController(this,store).retry(new JSONObject().put("request_id",action[0]).put("backup_id",id).put("expected_record_hash",job.getString("record_hash")));FullBackupJob.schedule(this,0);ui(()->{overall.setText("Erneuter Versuch lokal vorgemerkt. Status prüfen; eine externe Sicherung ist damit noch nicht bestätigt.");refresh(false);});}});});}
        }
        jobOffset+=list==null?0:list.length();moreJobs.setVisibility(jobOffset<jobsTotal?View.VISIBLE:View.GONE);moreJobs.setEnabled(true);
        requestBackup.setText(!backupRequest.isEmpty()?"Status der angeforderten Sicherung prüfen":!activeBackupId.isEmpty()?"Vorhandene Sicherung fortsetzen und prüfen":"Jetzt vollständig sichern");newGeneration.setVisibility(backupRequest.isEmpty()&&activeBackupId.isEmpty()?View.GONE:View.VISIBLE);
    }
    private void loadOlderJobs(){if(jobOffset>=jobsTotal)return;moreJobs.setEnabled(false);int offset=jobOffset;long serial=refreshSerial.get();WORK.execute(()->{try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject result=new FullBackupController(this,store).status(new JSONObject().put("offset",offset).put("limit",30));ui(()->{if(serial!=refreshSerial.get())return;jobsTotal=result.optInt("total",jobsTotal);renderJobs(result.optJSONArray("jobs"));});}catch(Exception failure){ui(()->{if(serial!=refreshSerial.get())return;moreJobs.setEnabled(true);showError(safeCode(failure));});}});}
    private void renderProviderStatus(TextView view,JSONObject value,boolean plain){String checked=value.optString("verified_at");view.setText((plain?"Klartextexport":"USB-/Dateianbietersicherung")+": "+value.optString("phase")+"\nEnthaltener Datenstand: "+time(value.optString("captured_at"))+"\nAm gewählten Ziel zurückgelesen: "+time(checked)+"\nDies bestätigt keinen unabhängigen Cloud-Upload."+(value.optString("last_error_code").isEmpty()?"":"\nHinweis: "+value.optString("last_error_code")));}
    private void renderPendingRestore(JSONObject value){String phase=value.optString("phase"),id=value.optString("restore_id");if(phase.equals("NONE")||!restoreId.isEmpty()&&!restoreId.equals(id))return;restoreId=id;restoreHash=value.optString("preview_hash");activateRestore.setVisibility(View.GONE);cancelRestore.setVisibility(Arrays.asList("RESTART_REQUIRED","ROLLED_BACK").contains(phase)?View.VISIBLE:View.GONE);restoreStatus.setText(phase.equals("RESTART_REQUIRED")?"Geprüfte Wiederherstellung für den geschützten Neustart vorgemerkt. Aktiver Bestand noch unverändert. App vollständig schließen und erneut öffnen; eine erfolgreiche Aktivierung ist noch nicht bestätigt.":phase.equals("ACTIVE")?"Der geprüfte Ersatzbestand wurde aktiviert. Neue Rechnungsausgabe bleibt bis zum aktuellen externen Beleg-/Nummernabgleich gesperrt.":"Wiederherstellungsstatus: "+phase+". "+(value.optBoolean("current_state_unchanged")?"Aktiver Bestand unverändert. ":"")+"Bei ausstehender Prüfung keine erfolgreiche Wiederherstellung bestätigt.");if(value.optString("media_coverage").equals("LEGACY_NOT_PROVEN"))restoreStatus.append("\nDie historische Vollständigkeit früherer Fotoentwürfe ist nicht belegt; eine vollständige historische Medienwiederherstellung wird nicht bestätigt.");}
    private void cancelRestore(){if(busy||restoreId.isEmpty()||restoreHash.isEmpty())return;new AlertDialog.Builder(this).setTitle("Vormerkung aufheben?").setMessage("Die noch nicht aktivierte oder vollständig zurückgerollte Wiederherstellungsvormerkung ausdrücklich aufheben? Aktive Geschäftsdaten werden nicht ersetzt.").setNegativeButton("Abbrechen",null).setPositiveButton("Vormerkung aufheben",(d,w)->run(()->{JSONObject result=new BackupRestoreService(this).cancelActivation(UUID.randomUUID().toString(),restoreId,restoreHash);ui(()->{renderPendingRestore(result);overall.setText("Vormerkung aufgehoben. Falls der geschützte Betrieb noch einen Neustart verlangt, die App vollständig schließen und erneut öffnen.");});})).show();}
    private static String phaseLabel(String phase){switch(phase){case "REMOTE_VERIFIED":return "Drive-Datei vollständig zurückgelesen und geprüft";case "PROVIDER_VERIFIED":return "Dateianbieter vollständig zurückgelesen · Upload nur mit unabhängigem Nachweis bestätigt";case "LOCAL_VERIFIED":return "Lokal geprüft · externe Sicherung noch ausstehend";case "UPLOAD_PENDING":case "UPLOADING":return "Drive-Upload ausstehend oder in Arbeit";case "REMOTE_VERIFY_PENDING":return "Upload übergeben · externe Prüfung ausstehend";case "NEEDS_USER_ACTION":case "FAILED":return "Sicherungsjob benötigt Prüfung";case "RETRY_PENDING":return "Erneuter Versuch vorgemerkt";case "CAPTURE_PENDING":case "CAPTURING":case "CAPTURED":case "SEALING":case "SEALED_LOCAL":return "Lokale Vollsicherung wird vorbereitet";case "CANCELLED":return "Sicherungsjob bewusst beendet";default:return "Sicherungszustand: "+phase;}}
    private void saveSetup(){
        account.setError(null);folder.setError(null);if(account.getText().toString().trim().isEmpty()){account.setError("Bitte ein bestehendes Google-Konto auswählen.");return;}final String folderId;try{folderId=DriveRestClient.folderId(folder.getText().toString());}catch(Exception invalid){folder.setError("Bitte einen gültigen Drive-Ordnerlink oder eine Ordner-ID eingeben.");return;}
        String chosen=account.getText().toString().trim(),revision=settingsRevision;boolean auto=automatic.isChecked(),wifi=unmetered.isChecked();String body=chosen+"\n"+folderId+"\n"+auto+"\n"+wifi+"\n"+revision;if(!body.equals(setupBody)){setupBody=body;setupRequest=UUID.randomUUID().toString();}String request=setupRequest;
        run(()->{try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject result=new BackupSettingsRepository(this,store).configure(request,revision,auto,chosen,folderId,wifi);FullBackupJob.install(this);if(auto)FullBackupJob.schedule(this,0);ui(()->{settingsRevision=result.optString("revision");dirty=false;setup.setVisibility(View.GONE);retrySetup.setVisibility(View.GONE);overall.setText("Sicherungsziel lokal gespeichert. Zugriff und externe Sicherung sind erst nach vollständigem Rücklesen bestätigt.");refresh(false);});}});
    }
    private void compareSetup(){run(()->{try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject latest=new BackupSettingsRepository(this,store).read();ui(()->new AlertDialog.Builder(this).setTitle("Einrichtung vergleichen").setMessage("Aktuell gespeichert:\n"+latest.optString("account")+"\n"+latest.optString("folderId")+"\nAutomatik: "+latest.optBoolean("enabled")+"\n\nDeine geöffneten Eingaben für diesen aktuellen Stand behalten? Anschließend ausdrücklich speichern.").setNegativeButton("Abbrechen",null).setPositiveButton("Eingaben behalten",(d,w)->{settingsRevision=latest.optString("revision");setupRequest="";setupBody="";retrySetup.setVisibility(View.GONE);dirty=true;}).show());}});}
    private void checkDriveAccess(){final String chosen=account.getText().toString().trim(),id;try{id=DriveRestClient.folderId(folder.getText().toString());if(chosen.isEmpty())throw new IOException();}catch(Exception invalid){folder.setError("Zuerst Konto und gültigen Sicherungsordner wählen.");return;}run(()->{String granted=DriveAccount.token(this,chosen,this);new DriveRestClient(id,()->granted,new DriveRestClient.HttpWire(),new DriveRestClient.Checkpoints(){public String get(String key){return "";}public void put(String key,String value){}}).validateFolder();ui(()->overall.setText("Konto und Ordnerzugriff jetzt geprüft. Es wurde keine Datei geändert und noch keine Vollsicherung bestätigt."));});}
    private void requestBackup(){if(busy)return;if(dirty){overall.setText("Die geänderte Einrichtung ist noch nicht gespeichert. Zuerst speichern oder bewusst verwerfen; eine neue Sicherung verwendet nur das gespeicherte Ziel.");return;}if(status.optBoolean("browser_capture_pending")){overall.setText("Die Erfassung der aktuellen Formularwerte läuft noch. Status prüfen und danach ausdrücklich sichern.");return;}String hash=status.optString("settings_hash");if(hash.isEmpty()){showError("BACKUP_SETTINGS_REVISION_REQUIRED");return;}if(backupRequest.isEmpty()){backupRequest=UUID.randomUUID().toString();backupRequestSettings=hash;}String request=backupRequest,settings=backupRequestSettings;run(()->{try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject result=new FullBackupController(this,store).request(new JSONObject().put("request_id",request).put("expected_settings_hash",settings));String id=result.optString("backup_id");FullBackupJob.schedule(this,0);ui(()->{lastRequestedBackup=id;overall.setText("Vollsicherung lokal angefordert. Vorbereitung funktioniert ohne Netz; ein Upload wartet gegebenenfalls auf die gewählte Verbindung. Status prüfen.");requestBackup.setText("Status der angeforderten Sicherung prüfen");newGeneration.setVisibility(View.VISIBLE);refresh(false);});}});}
    private void createRecovery(){if(candidateCode!=null){recoveryStatus.setText("Der vorbereitete Code bleibt unverändert angezeigt. Zuerst separat aufbewahren und zurückbestätigen; er wird nicht durch einen zweiten Klick ersetzt.");return;}run(()->{BackupRecoveryKeyStore keys=new BackupRecoveryKeyStore(this);if(keys.configured()){ui(()->recoveryStatus.setText("Ein bestätigter Code ist bereits geschützt. Er wird nicht still ersetzt. Über „Code separat als Datei speichern“ kann er nach Gerätefreigabe erneut exportiert werden."));return;}String code=BackupCrypto.newRecoveryCode();ui(()->{candidateCode=code;recoveryRequest=UUID.randomUUID().toString();codeView.setText(code);codeView.setVisibility(View.VISIBLE);confirmation.setText("");codeSeparate.setChecked(false);recoveryStatus.setText("Diesen Code getrennt aufbewahren. Nach einem Prozessende wird ein unbestätigter Code verworfen; nur der ausdrücklich bestätigte Code schützt spätere Sicherungen.");});});}
    private void exportRecovery(){if(busy)return;if(candidateCode!=null){pendingCodeExport=candidateCode;chooseCodeDocument();return;}KeyguardManager lock=getSystemService(KeyguardManager.class);if(lock==null||!lock.isDeviceSecure()){showError("DEVICE_LOCK_REQUIRED_FOR_RECOVERY_EXPORT");return;}Intent intent=lock.createConfirmDeviceCredentialIntent("Wiederherstellungscode exportieren","Bestätige die Gerätesperre, um den bestehenden Code separat zu speichern.");if(intent==null){showError("DEVICE_CONFIRMATION_UNAVAILABLE");return;}startActivityForResult(intent,DEVICE_CONFIRM);}
    private void chooseCodeDocument(){Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/plain").putExtra(Intent.EXTRA_TITLE,"HG-Wiederherstellungscode.txt");try{startActivityForResult(intent,CODE_DOCUMENT);}catch(ActivityNotFoundException unavailable){pendingCodeExport=null;showError("DOCUMENT_PICKER_UNAVAILABLE");}}
    private void confirmRecovery(){secretErrorField=confirmation;confirmation.setError(null);if(candidateCode==null){showError("RECOVERY_NOT_CONFIGURED");return;}if(!codeSeparate.isChecked()){recoveryStatus.setText("Bitte den Code zuerst getrennt aufbewahren und diese Aufbewahrung bestätigen.");return;}String candidate=candidateCode,confirmed=confirmation.getText().toString(),request=recoveryRequest;run(()->{new BackupRecoveryKeyStore(this).confirmAndStore(request,candidate,confirmed);ui(()->{candidateCode=null;pendingCodeExport=null;codeView.setText("");codeView.setVisibility(View.GONE);confirmation.setText("");recoveryStatus.setText("Code zurückbestätigt und im Keystore geschützt. Separate Kopie aufbewahren.");refresh(false);});});}
    private void confirmRepair(){if(busy)return;secretErrorField=repairConfirmation;repairCode.setError(null);repairConfirmation.setError(null);if(repairBackupId.isEmpty()){repairStatus.setText("Zuerst unten eine lokal geprüfte Sicherung für die Reparatur auswählen.");return;}new AlertDialog.Builder(this).setTitle("Lokalen Schlüsselschutz ausdrücklich reparieren?").setMessage("Die gewählte vollständige Sicherung mit dem eingegebenen Code authentifizieren und ihre Beziehungen prüfen. Nur eine unlesbare bestehende Kapsel wird ersetzt; ihre bisherigen Bytes und Schlüssel bleiben erhalten. Geschäftsdaten werden dabei nicht wiederhergestellt.").setNegativeButton("Abbrechen",null).setPositiveButton("Prüfen und reparieren",(dialog,which)->{String request=repairRequest,id=repairBackupId,code=repairCode.getText().toString(),confirmation=repairConfirmation.getText().toString();run(()->{try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject result=new BackupRecoveryRepairService(this,store).repair(request,id,code,confirmation);ui(()->{repairCode.setText("");repairConfirmation.setText("");repairStatus.setText(result.optBoolean("repaired")?"Der Schlüsselschutz wurde nach vollständiger Prüfung repariert und zurückgelesen. Alte Kapsel und bisheriger Alias bleiben erhalten. Geschäftsdaten wurden nicht ersetzt.":"Keine Reparatur bestätigt. Status prüfen.");refresh(false);});}});}).show();}
    private void selectUsb(){run(()->{if(!new BackupRecoveryKeyStore(this).configured())throw new IOException("RECOVERY_NOT_CONFIGURED");ui(()->{if(!exportRequest.isEmpty())new AlertDialog.Builder(this).setTitle("USB-Sicherung").setMessage("Den bisherigen USB-Auftrag am selben Ziel fortsetzen oder bewusst eine neue Generation anfordern?").setNegativeButton("Abbrechen",null).setNeutralButton("Bisherigen Auftrag fortsetzen",(d,w)->{if(exportTree.isEmpty())pickUsb();else exportToUsb(Uri.parse(exportTree),false);}).setPositiveButton("Neue Generation",(d,w)->{exportRequest="";exportTree="";pickUsb();}).show();else pickUsb();});});}
    private void pickUsb(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,USB_TREE);}catch(ActivityNotFoundException unavailable){showError("DOCUMENT_PICKER_UNAVAILABLE");}}
    private void exportToUsb(Uri tree,boolean persist){if(exportRequest.isEmpty())exportRequest=UUID.randomUUID().toString();String request=exportRequest;exportTree=tree.toString();run(()->{if(persist)getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject result=new BackupSafService(this,store).createAndExport(request,tree);ui(()->renderProviderStatus(jobStatus,result,false));}});}
    private void selectPortable(){if(busy)return;if(!portableRequest.isEmpty())new AlertDialog.Builder(this).setTitle("Klartextexport").setMessage("Einen bestehenden Export am selben Ziel fortsetzen oder eine neue Generation aus dem aktuellen Stand erstellen?").setNegativeButton("Abbrechen",null).setNeutralButton("Bestehenden Export fortsetzen",(d,w)->{if(portableTree.isEmpty())pickPortable();else confirmPortable(Uri.parse(portableTree),false);}).setPositiveButton("Neue Exportgeneration",(d,w)->{portableRequest="";portableTree="";pickPortable();}).show();else pickPortable();}
    private void pickPortable(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,PORTABLE_TREE);}catch(ActivityNotFoundException unavailable){showError("DOCUMENT_PICKER_UNAVAILABLE");}}
    private void confirmPortable(Uri tree,boolean persist){try{BackupPortableExport.requireLocalDestination(tree);}catch(IOException refused){showError("PORTABLE_LOCAL_DESTINATION_REQUIRED");return;}new AlertDialog.Builder(this).setTitle("Klartext bewusst exportieren?").setMessage("Der unverschlüsselte Export enthält Kunden- und Leistungsdaten, Fotos und PDF-Originale. Das gerade gewählte Ziel und die Aufbewahrung liegen in deiner Verantwortung. Es ist kein verschlüsselter Wiederherstellungsstand. Bewusst an dieses Ziel exportieren?").setNegativeButton("Abbrechen",null).setPositiveButton("Klartextexport ausdrücklich erstellen",(dialog,which)->{if(portableRequest.isEmpty())portableRequest=UUID.randomUUID().toString();portableTree=tree.toString();String request=portableRequest;run(()->{if(persist)getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try(PixelLocalStore store=new PixelLocalStore(this)){JSONObject result=new BackupPortableExport(this,store).createAndExport(request,tree,true);ui(()->renderProviderStatus(portableStatus,result,true));}});}).show();}
    private void renderPrevious(JSONObject value){String activation=value.optBoolean("available")?value.optString("activation_request_id"):"";if(!previousActivation.equals(activation))previousPreviewRequest="";previousActivation=activation;previewPrevious.setVisibility(activation.isEmpty()?View.GONE:View.VISIBLE);previousStatus.setText(activation.isEmpty()?"Ein geschützter Stand vor einer Wiederherstellung ist noch nicht nachgewiesen.":"Geschützter Stand vor Wiederherstellung verfügbar. Datenstand: "+time(value.optString("captured_at"))+" · "+value.optLong("byte_size")+" Byte. Zur Prüfung den zu diesem Stand gehörenden Code eingeben; der aktive Bestand bleibt zunächst unverändert.");}
    private void renderPreview(JSONObject result)throws JSONException {JSONObject summary=result.getJSONObject("summary");restoreCode.setText("");restoreId=result.optString("restore_id");restoreHash=result.optString("preview_hash");restoreLegacyMedia=summary.optString("media_coverage","LEGACY_NOT_PROVEN").equals("LEGACY_NOT_PROVEN");legacyMediaCoverage.setChecked(false);legacyMediaCoverage.setVisibility(restoreLegacyMedia?View.VISIBLE:View.GONE);restoreStatus.setText((restoreLegacyMedia?"Enthaltener Ersatzbestand geprüft. Bei dieser alten Sicherung ist die Vollständigkeit früherer Fotoentwürfe nicht belegt. Eine bewusste Rettung des enthaltenen Bestands braucht die zusätzliche Bestätigung unten.":"Ersatzbestand einschließlich nativer Medienreferenzen vollständig geprüft.")+" Datenstand: "+time(summary.optString("captured_at"))+"\nSchema: "+summary.optInt("schema_version")+" · Dateien insgesamt: "+summary.optLong("total_bytes")+" Byte\nAktiver Bestand unverändert. Rechnungsfreigabe bleibt gesperrt.");activateRestore.setVisibility(View.VISIBLE);}
    private void previewRestore(){secretErrorField=restoreCode;restoreCode.setError(null);if(restoreUri.isEmpty()){restoreStatus.setText("Zuerst eine verschlüsselte Sicherungsdatei auswählen.");return;}if(restoreRequest.isEmpty())restoreRequest=UUID.randomUUID().toString();String request=restoreRequest,code=restoreCode.getText().toString();Uri uri=Uri.parse(restoreUri);run(()->{JSONObject result=new BackupRestoreService(this).preview(request,uri,code);ui(()->{try{renderPreview(result);}catch(JSONException invalid){showError("RESTORE_PREVIEW_INVALID");}});});}
    private void previewPrevious(){if(busy||previousActivation.isEmpty())return;secretErrorField=restoreCode;restoreCode.setError(null);if(previousPreviewRequest.isEmpty())previousPreviewRequest=UUID.randomUUID().toString();String request=previousPreviewRequest,activation=previousActivation,code=restoreCode.getText().toString();run(()->{JSONObject result=new BackupRestoreService(this).previewPrevious(request,activation,code);ui(()->{try{renderPreview(result);}catch(JSONException invalid){showError("RESTORE_PREVIEW_INVALID");}});});}
    private void confirmRestore(){if(restoreId.isEmpty()||restoreHash.isEmpty())return;if(restoreLegacyMedia&&!legacyMediaCoverage.isChecked()){restoreStatus.setText("Die unbelegte Vollständigkeit früherer Fotoentwürfe dieser alten Sicherung muss separat bestätigt werden. Der aktive Bestand bleibt unverändert.");return;}final boolean legacyConfirmed=restoreLegacyMedia&&legacyMediaCoverage.isChecked();new AlertDialog.Builder(this).setTitle("Aktiven Bestand ausdrücklich ersetzen?").setMessage("Den geprüften enthaltenen Ersatzbestand für den geschützten Neustart vormerken? Es gibt keine automatische Vermischung. Vor dem Austausch muss der aktuelle Stand tatsächlich geschützt sein. Rechnungen bleiben bis zum aktuellen externen Belegabgleich gesperrt.").setNegativeButton("Abbrechen",null).setPositiveButton("Wiederherstellung vormerken",(dialog,which)->{String request=UUID.randomUUID().toString();run(()->{JSONObject result=new BackupRestoreService(this).requestActivation(request,restoreId,restoreHash,true,legacyConfirmed);ui(()->{activateRestore.setEnabled(false);restoreStatus.setText("Wiederherstellung vorgemerkt: "+result.optString("phase")+". Aktiver Bestand noch unverändert. App vollständig schließen und erneut öffnen; der geschützte Start prüft die Aktivierung. Bis dahin keine erfolgreiche Wiederherstellung bestätigt.");});});}).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK){if(request==CODE_DOCUMENT)pendingCodeExport=null;return;}
        if(request==ACCOUNT&&data!=null){String chosen=data.getStringExtra(AccountManager.KEY_ACCOUNT_NAME);if(chosen!=null){account.setText(chosen);dirty=true;}return;}
        if(request==DEVICE_CONFIRM){run(()->{String code=new BackupRecoveryKeyStore(this).read();ui(()->{pendingCodeExport=code;chooseCodeDocument();});});return;}
        if(data==null||data.getData()==null)return;Uri uri=data.getData();if(!"content".equals(uri.getScheme())){pendingCodeExport=null;showError("DOCUMENT_URI_REQUIRED");return;}
        if((request==USB_TREE||request==PORTABLE_TREE)&&(data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION))!=(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION)){showError("DOCUMENT_READ_WRITE_PERMISSION_REQUIRED");return;}
        if(request==CODE_DOCUMENT){String code=pendingCodeExport;pendingCodeExport=null;if(code==null){showError("RECOVERY_EXPORT_RETRY_REQUIRED");return;}run(()->{byte[] bytes=(code+"\n").getBytes(StandardCharsets.US_ASCII);try(OutputStream output=getContentResolver().openOutputStream(uri,"w")){if(output==null)throw new IOException("RECOVERY_EXPORT_UNAVAILABLE");output.write(bytes);output.flush();}ByteArrayOutputStream copy=new ByteArrayOutputStream();try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("RECOVERY_EXPORT_UNAVAILABLE");byte[] block=new byte[256];int n;while((n=input.read(block))!=-1){if(n>4096-copy.size())throw new IOException("RECOVERY_EXPORT_READBACK_FAILED");copy.write(block,0,n);}}if(!MessageDigest.isEqual(bytes,copy.toByteArray()))throw new IOException("RECOVERY_EXPORT_READBACK_FAILED");ui(()->recoveryStatus.setText("Code am gewählten Ziel zurückgelesen. Getrennt von Gerät und Sicherungsarchiv aufbewahren; bei Cloud-Dateianbietern den tatsächlichen Upload zusätzlich prüfen. Jetzt den gespeicherten Code zurückbestätigen."));});}
        else if(request==USB_TREE)exportToUsb(uri,true);
        else if(request==PORTABLE_TREE)confirmPortable(uri,true);
        else if(request==RESTORE_DOCUMENT){if((data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)==0){showError("DOCUMENT_READ_PERMISSION_REQUIRED");return;}try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){/* A temporary read grant may still permit the explicit preview. */}restoreUri=uri.toString();restoreRequest="";restoreId="";restoreHash="";activateRestore.setVisibility(View.GONE);restoreStatus.setText("Sicherungsdatei gewählt. Code eingeben und vollständig prüfen.");}
    }
    private void restoreNonSecretState(Bundle saved){if(saved==null)return;backupRequest=saved.getString("backup_request","");backupRequestSettings=saved.getString("backup_request_settings","");lastRequestedBackup=saved.getString("last_backup","");setupRequest=saved.getString("setup_request","");setupBody=saved.getString("setup_body","");exportRequest=saved.getString("export_request","");exportTree=saved.getString("export_tree","");portableRequest=saved.getString("portable_request","");portableTree=saved.getString("portable_tree","");restoreUri=saved.getString("restore_uri","");restoreRequest=saved.getString("restore_request","");if(!restoreUri.isEmpty())restoreStatus.setText("Dateiauswahl erhalten. Code bitte erneut eingeben; ohne Code keine neue Prüfung.");}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(account==null)return;out.putBoolean("setup_dirty",dirty);out.putString("account",account.getText().toString());out.putString("folder",folder.getText().toString());out.putBoolean("automatic",automatic.isChecked());out.putBoolean("unmetered",unmetered.isChecked());out.putString("settings_revision",settingsRevision);out.putString("setup_request",setupRequest);out.putString("setup_body",setupBody);out.putString("backup_request",backupRequest);out.putString("backup_request_settings",backupRequestSettings);out.putString("last_backup",lastRequestedBackup);out.putString("export_request",exportRequest);out.putString("export_tree",exportTree);out.putString("portable_request",portableRequest);out.putString("portable_tree",portableTree);out.putString("restore_request",restoreRequest);out.putString("restore_uri",restoreUri);/* Recovery codes and confirmation fields are deliberately never serialized. */}
    private void leave(){if(busy){new AlertDialog.Builder(this).setTitle("Laufenden Vorgang unterbrechen?").setMessage("Den angeforderten Vorgang unterbrechen und zur App zurückkehren? Unvollständige Generationen werden nicht als geprüft bestätigt. Die letzte gute Sicherung und der aktive Bestand bleiben geschützt.").setNegativeButton("Weiter warten",null).setPositiveButton("Unterbrechen und zurück",(d,w)->{if(currentTask!=null)currentTask.cancel(true);finish();}).show();return;}if(dirty||candidateCode!=null||confirmation.length()>0||restoreCode.length()>0||repairCode.length()>0||repairConfirmation.length()>0)new AlertDialog.Builder(this).setTitle("Einrichtung verlassen?").setMessage("Ungespeicherte Einrichtung oder noch eingegebene Codes verwerfen? Bereits bestätigte Sicherungen und Geschäftsdaten bleiben erhalten.").setNegativeButton("Weiter bearbeiten",null).setPositiveButton("Ungespeicherte Eingaben verwerfen",(d,w)->finish()).show();else finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){if(Build.VERSION.SDK_INT<33)leave();}
    @Override protected void onDestroy(){candidateCode=null;pendingCodeExport=null;if(codeView!=null)codeView.setText("");if(confirmation!=null)confirmation.setText("");if(restoreCode!=null)restoreCode.setText("");if(repairCode!=null)repairCode.setText("");if(repairConfirmation!=null)repairConfirmation.setText("");if(Build.VERSION.SDK_INT>=33&&backCallback!=null)getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback(backCallback);super.onDestroy();}
